def distribute_by_appearance_level(grid):
    """Distribute pixels by their appearance level (1st, 2nd, etc.)"""
    rows, cols = len(grid), len(grid[0])

    # Group pixels by color
    color_positions = {}
    for r in range(rows - 1):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                if v not in color_positions:
                    color_positions[v] = []
                color_positions[v].append((r, c))

    print("Pixels grouped by color:")
    for color, positions in sorted(color_positions.items()):
        print(f"  {color}: {positions}")

    result = [[0]*cols for _ in range(rows)]

    # For each color, distribute its pixels across output rows
    start_row = max(0, rows - 4)  # Row 6

    for color, positions in color_positions.items():
        # Determine how many distinct output rows this color uses
        num_outputs = min(len(positions), rows - start_row - 1)

        # Distribute positions across available output rows
        pos_idx = 0
        for out_r in range(start_row, start_row + num_outputs):
            for inp_c, _ in positions[pos_idx:pos_idx+cols]:
                if inp_c < cols:
                    result[out_r][inp_c] = color
            pos_idx += 1

    return result

