def compute_by_color_rank(grid):
    rows, cols = len(grid), len(grid[0])

    # Find first appearance row for each color
    first_appear = {}
    for r in range(rows - 1):
        for c in range(cols):
            v = grid[r][c]
            if v != 0 and v not in first_appear:
                first_appear[v] = r

    # Sort colors by first appearance row (stable sort preserves column order for ties)
    sorted_colors = sorted(first_appear.keys(), key=lambda c: first_appear[c])

    print(f"\nColors sorted by first appearance row:")
    for v in sorted_colors:
        print(f"  Color {v}: first at row {first_appear[v]}")

    result = [[0]*cols for _ in range(rows)]
    start_row = max(0, rows - 4)  # Row 6 for 10-row grid

    # Assign each color a "base row" based on its sort rank
    # But cap it so we don't overflow
    for color_rank, color in enumerate(sorted_colors):
        base_row = min(start_row + color_rank, rows - 2)

        # Place all pixels of this color at their original positions but in new row
        for r in range(rows - 1):
            for c in range(cols):
                if grid[r][c] == color:
                    result[base_row][c] = color

    return result

