def stack_components(grid):
    rows, cols = len(grid), len(grid[0])

    visited = set()
    components = []

    # Find all components
    for r in range(rows - 1):
        for c in range(cols):
            if grid[r][c] != 0 and (r,c) not in visited:
                component = []
                color = grid[r][c]
                queue = [(r,c)]
                visited.add((r,c))
                while queue:
                    cr, cc = queue.pop(0)
                    component.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                comp = {
                    'color': color,
                    'pixels': sorted(component),
                    'first_pos': min(component),
                    'area': len(component)
                }
                components.append(comp)

    print(f"Found {len(components)} components")

    result = [[0]*cols for _ in range(rows)]
    start_row = max(0, rows - 4)

    # Sort by first appearance row, then col
    components.sort(key=lambda c: (c['first_pos'][0], c['first_pos'][1]))

    print("\nSorted components:")
    for i, c in enumerate(components):
        print(f"  {i}: color={c['color']}, first={c['first_pos']}")

    # Now map each input pixel to output based on sorted order of components
    # Color with earliest appearance gets higher priority (lower output row)
    color_rank = {c['color']: i for i, c in enumerate(components)}

    for r in range(rows - 1):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                # Place at row determined by component rank
                # Higher rank = lower output row
                out_r = start_row + 2 - color_rank[v]  # Invert so earlier = top

                if out_r >= 0 and out_r < rows - 1:
                    result[out_r][c] = v
                else:
                    print(f"Warning: can't place {v} at ({r},{c}) -> out_r={out_r}")

    return result

