def stack_columns_by_pixel_count(grid):
    """For each column, extract pattern and stack based on pixel count + first-appearance."""
    rows, cols = len(grid), len(grid[0])

    # Extract non-zero patterns for each column
    col_patterns = []
    for c in range(cols):
        pixels = []
        first_r = None
        for r in range(rows - 1):
            v = grid[r][c]
            if v != 0:
                pixels.append(v)
                if first_r is None:
                    first_r = r
        col_patterns.append({
            'orig_col': c,
            'pattern': tuple(pixels) if pixels else None,
            'pixel_count': len(pixels),
            'first_row': first_r
        })

    print("Column patterns:")
    for cp in col_patterns:
        print(f"  Col {cp['orig_col']}: count={cp['pixel_count']}, first={cp['first_row']}, pattern={cp['pattern']}")

    # Sort by: pixel_count DESC, then first_row ASC
    col_patterns.sort(key=lambda c: (-c['pixel_count'], c['first_row']))

    print("\nSorted columns:")
    for cp in col_patterns:
        print(f"  orig_col={cp['orig_col']}, count={cp['pixel_count']}, first={cp['first_row']}")

    result = [[0]*cols for _ in range(rows)]
    start_row = max(0, rows - 4)

    # Assign each sorted column a starting output row
    # Top-ranked column starts earliest

    for rank, cp in enumerate(col_patterns):
        out_start_r = start_row + rank
        pattern = cp['pattern']

        if pattern is not None:
            for idx, v in enumerate(pattern):
                out_r = out_start_r + idx
                if out_r < rows - 1:
                    result[out_r][cp['orig_col']] = v

    return result

